 const string FacilityArt="Assets/_Game/Art/FacilityStandardization/";
 static Sprite[] facilityActivities,facilityEmpty,facilityFurniture,facilityDining;
 static Sprite[] FacilityAtlas(string file){string path=FacilityArt+file+".png";var ti=(TextureImporter)AssetImporter.GetAtPath(path);if(ti==null)throw new Exception("Missing art "+path);ti.textureType=TextureImporterType.Sprite;ti.spriteImportMode=SpriteImportMode.Multiple;ti.filterMode=FilterMode.Point;ti.mipmapEnabled=false;ti.alphaIsTransparency=true;ti.textureCompression=TextureImporterCompression.Uncompressed;ti.GetSourceTextureWidthAndHeight(out int w,out int h);ti.spritePixelsPerUnit=w/4f/2.7f;ti.maxTextureSize=2048;var parts=new SpriteMetaData[16];for(int y=0;y<4;y++)for(int x=0;x<4;x++)parts[y*4+x]=new SpriteMetaData{name=file+"_"+(y*4+x).ToString("D2"),rect=new Rect(x*w/4f,h-(y+1)*h/4f,w/4f,h/4f),alignment=9,pivot=new Vector2(.5f,.04f)};ti.spritesheet=parts;ti.SaveAndReimport();return AssetDatabase.LoadAllAssetsAtPath(path).OfType<Sprite>().OrderBy(s=>s.name).ToArray();}
 static string FacilitySignature(string zone){var b=new StringBuilder();var roots=world.transform.Cast<Transform>().Where(t=>t.name.EndsWith(" / "+zone)).Concat(world.objects.Where(o=>o!=null&&o.zone==zone&&o.kind!=WorldInteractionKind.NPC).Select(o=>o.transform));foreach(var t in roots.SelectMany(t=>t.GetComponentsInChildren<Transform>(true)).Distinct().OrderBy(t=>t.name).ThenBy(t=>t.position.x).ThenBy(t=>t.position.y)){b.Append(t.name).Append(t.position.ToString("F5")).Append(t.localScale.ToString("F5")).Append(t.rotation.ToString("F5"));foreach(var c in t.GetComponents<Component>())if(c!=null)b.Append(EditorJsonUtility.ToJson(c));}using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(b.ToString()))).Replace("-","");}
 static void FacilityDecor(Transform root,string name,int item,Vector2 p,float width){var sr=Image(root,name,facilityFurniture[item],p);sr.enabled=true;sr.transform.localScale=Vector3.one*width/Mathf.Max(.01f,sr.sprite.bounds.size.x);if(new[]{5,8,9,10,11,12,15}.Contains(item)){var c=Component<BoxCollider2D>(sr.gameObject);c.size=new Vector2(sr.sprite.bounds.size.x*.8f,.35f/sr.transform.localScale.y);c.offset=new Vector2(0,.25f/sr.transform.localScale.y);}}
 static void FacilityAnchors(WorldActivitySlot slot,Vector2 seat,Vector2 approach,Vector2 stand,bool seated,ActorMotion motion,Vector2 facing){slot.useSeatAnchors=true;slot.seated=seated;slot.activityMotion=motion;slot.facing=facing;slot.seatAnchor=Child(slot.transform,"SeatAnchor");slot.approachAnchor=Child(slot.transform,"ApproachPoint");slot.standUpAnchor=Child(slot.transform,"StandUpPoint");slot.seatAnchor.localPosition=seat;slot.approachAnchor.localPosition=approach;slot.standUpAnchor.localPosition=stand;}
 static WorldInteractable FacilityStation(string id,string title,string zone,Vector2 p,int row,string owner,bool seated,Vector2 facing){var o=Prop(id,title,zone,p,facilityEmpty[row*4],seated?WorldInteractionKind.Rest:WorldInteractionKind.Work,1);o.enabled=false;var slot=Component<WorldActivitySlot>(o.gameObject);slot.staffId=owner;slot.seat=null;var col=o.GetComponent<BoxCollider2D>();col.size=new Vector2(row==2?2.2f:1.45f,.45f);col.offset=new Vector2(0,.85f);var seat=new Vector2(0,.16f);FacilityAnchors(slot,seat,new Vector2(.85f,-.55f),new Vector2(.85f,-.55f),seated,row==1?ActorMotion.UseComputer:row==3?ActorMotion.Eat:ActorMotion.Work,facing);var presentation=Component<WorldFacilityActivityPresentation>(o.gameObject);presentation.slot=slot;presentation.empty=o.visual;presentation.frames=facilityActivities.Skip(row*4).Take(4).ToArray();presentation.occupied=Image(o.transform,"Occupied activity",presentation.frames[0],Vector2.zero);presentation.occupied.enabled=false;return o;}
 static WorldInteractable FacilityPoint(string id,string title,string zone,Vector2 p,string owner,Vector2 facing,ActorMotion motion=ActorMotion.Idle){var o=Find(id);if(o==null){o=new GameObject(id,typeof(WorldInteractable)).GetComponent<WorldInteractable>();o.transform.SetParent(world.transform,false);world.objects=world.objects.Concat(new[]{o}).ToArray();}o.id=id;o.title=title;o.zone=zone;o.UsePoint=Vector2.zero;o.kind=WorldInteractionKind.Rest;o.transform.position=rules.Zone(zone).origin+p;o.enabled=false;var slot=Component<WorldActivitySlot>(o.gameObject);slot.staffId=owner;FacilityAnchors(slot,Vector2.zero,Vector2.zero,new Vector2(.55f,-.35f),false,motion,facing);return o;}
 static NPCScheduleEntry FacilityAt(int minute,string zone,string id,NPCDailyAction action,int mask=127){var o=Find(id);return new NPCScheduleEntry{hour=minute/60,minute=minute%60,dayMask=mask,zone=zone,objectId=id,action=action,position=o==null?new Vector2(-8,1.5f):o.Point-rules.Zone(zone).origin};}
