 [Serializable]class FacilityScheduleSource {public WorldNPCDefinition[] npcs;}
 static void FacilitySchedules(){var original=JsonUtility.FromJson<FacilityScheduleSource>(File.ReadAllText("Assets/_Game/Data/FacilityStandardizationBaseline.json"));
  for(int i=0;i<rules.npcs.Length;i++){var d=rules.npcs[i];var night=original.npcs.FirstOrDefault(n=>n.npcId==d.npcId&&n.personality==NPCPersonality.NightWorker);if(night!=null)d.schedule=night.schedule;var appointments=d.schedule.Where(e=>e.action==NPCDailyAction.Talk&&(e.zone=="finance"||e.zone=="realestate")).ToArray();var appointmentTimes=new HashSet<int>(appointments.SelectMany(e=>new[]{e.hour*60+e.minute+20,e.hour*60+e.minute+28}));var list=d.schedule.Where(e=>!appointmentTimes.Contains(e.hour*60+e.minute)||e.action==NPCDailyAction.Talk).ToList();var meals=list.Where(e=>e.action==NPCDailyAction.Eat&&e.zone=="shop").ToArray();if(meals.Length==0){meals=new[]{FacilityAt(12*60,"shop","cafe-table-0",NPCDailyAction.Eat)};list.Add(meals[0]);}int start=night!=null?meals[0].hour*60+meals[0].minute:12*60+(i/4)*20;
   foreach(var meal in meals){meal.hour=start/60;meal.minute=start%60;meal.objectId="cafe-table-"+(i%4);meal.position=Find(meal.objectId).GetComponent<WorldActivitySlot>().Point-rules.Zone("shop").origin;}
   var next=night!=null?night.schedule.LastOrDefault(e=>e.action==NPCDailyAction.Rest&&e.hour*60+e.minute<start):d.schedule.FirstOrDefault(e=>e.hour*60+e.minute>=13*60&&e.action!=NPCDailyAction.Eat);if(next!=null){var end=FacilityAt(start+18,next.zone,next.objectId,next.action,meals[0].dayMask);end.position=next.position;if(!list.Any(e=>e.hour==end.hour&&e.minute==end.minute&&e.zone==end.zone&&e.objectId==end.objectId&&e.action==end.action))list.Add(end);}
   foreach(var shop in list.Where(e=>e.action==NPCDailyAction.Shop).ToArray()){int at=17*60+(i/6)*60+(i%6)*8;shop.hour=at/60;shop.minute=at%60;shop.objectId="shop-browse-"+(i%6);shop.position=Find(shop.objectId).Point-rules.Zone("shop").origin;var end=FacilityAt(at+7,"city","",NPCDailyAction.Walk,shop.dayMask);end.position=new Vector2(-10+i%5*2,1.5f);if(!list.Any(e=>e.hour==end.hour&&e.minute==end.minute&&e.zone==end.zone&&e.action==end.action))list.Add(end);}
   foreach(var appointment in appointments){int at=appointment.hour*60+appointment.minute;list.Add(FacilityAt(at+20,"shop","shop-browse-"+(i%6),NPCDailyAction.Shop,appointment.dayMask));var leave=FacilityAt(at+28,"city","",NPCDailyAction.Walk,appointment.dayMask);leave.position=new Vector2(-10+i%5*2,1.5f);list.Add(leave);}
   d.schedule=list.OrderBy(e=>e.hour*60+e.minute).ToArray();
  }
 }
 static void FacilityFinance(){foreach(string zone in new[]{"finance","realestate"}){var root=world.transform.Cast<Transform>().First(t=>t.name.EndsWith(" / "+zone));FacilityDecor(root,"Purposeful facility display",zone=="finance"?14:13,new Vector2(-2.5f,2.8f),4.4f);FacilityDecor(root,"Facility document storage",15,new Vector2(4.2f,1.3f),1.8f);var live=root.Find("Live facility board");if(live!=null){live.localPosition=new Vector2(3.2f,3.8f);live.GetComponent<SpriteRenderer>().size=new Vector2(4.5f,1.25f);}var values=root.Find("Live facility values");if(values!=null){values.localPosition=new Vector2(3.2f,3.8f);values.GetComponent<TMP_Text>().rectTransform.sizeDelta=new Vector2(4.1f,1.15f);values.GetComponent<TMP_Text>().fontSize=1.8f;}var heading=root.Find("Customer flow");if(heading!=null)heading.GetComponent<TMP_Text>().text="고객 상담 · 서류 확인";
   var consult=Find(zone+"-consultation-point");var slot=consult.GetComponent<WorldActivitySlot>();FacilityAnchors(slot,Vector2.zero,new Vector2(.65f,-.6f),new Vector2(.65f,-.6f),false,ActorMotion.Idle,Vector2.up);
   var waiting=Find(zone+"-waiting");waiting.transform.position=rules.Zone(zone).origin+new Vector2(-1.2f,-3);waiting.visual.sortingOrder=1300;
   var lounge=FacilityStation(zone+"-staff-rest-0","직원 음료·휴식 자리",zone,new Vector2(3.5f,-3),3,"",true,Vector2.down);var loungeVisual=lounge.GetComponent<WorldFacilityActivityPresentation>();loungeVisual.frames=facilityDining;loungeVisual.citizenRows=true;
   var oldRest=Find(zone+"-staff-rest-1");if(oldRest!=null){if(oldRest.visual!=null)oldRest.visual.enabled=false;foreach(var c in oldRest.GetComponents<Collider2D>())c.enabled=false;oldRest.enabled=false;}
   foreach(var d in rules.npcs)foreach(var e in d.schedule.Where(e=>e.zone==zone&&e.objectId.StartsWith(zone+"-staff-rest-"))){e.objectId=lounge.id;e.position=lounge.GetComponent<WorldActivitySlot>().Point-rules.Zone(zone).origin;}
  }}
 [MenuItem("Ian/Life World/Standardize Existing Facilities")]
 public static void StandardizeFacilities(){if(Application.isPlaying)throw new Exception("Stop Play first");var scene=EditorSceneManager.OpenScene("Assets/_Game/Scenes/LifeWorld.unity");world=UnityEngine.Object.FindAnyObjectByType<LifeWorldController>();rules=world.Service==null?AssetDatabase.LoadAssetAtPath<LifeWorldRules>("Assets/_Game/Data/Phase26/LifeWorldRules.asset"):world.Service.rules;art=AssetDatabase.LoadAllAssetsAtPath("Assets/_Game/Art/VisualRebuild/Architecture.png").OfType<Sprite>().ToDictionary(s=>s.name);Directory.CreateDirectory("Docs/FacilityStandardization");string officeBefore=FacilitySignature("workplace"),homeBefore=FacilitySignature("home");facilityActivities=FacilityAtlas("Activities");facilityEmpty=FacilityAtlas("EmptyActivities");facilityFurniture=FacilityAtlas("Furniture");facilityDining=FacilityAtlas("Dining");FacilitySchool();FacilityShop();FacilitySchedules();FacilityFinance();foreach(var targetZone in new[]{"school","shop"}){var room=world.transform.Cast<Transform>().First(t=>t.name.EndsWith(" / "+targetZone));var floor=room.Find("Walkable floor").GetComponent<SpriteRenderer>();floor.drawMode=SpriteDrawMode.Tiled;floor.size=rules.Zone(targetZone).size;floor.transform.localScale=Vector3.one;}foreach(var t in world.GetComponentsInChildren<TMP_Text>(true))if(t.text.Contains("배움터"))t.text=t.text.Replace("배움터","학교");Find("school-front").title="학교로 들어가기";Find("school-exit").title="학교에서 도시로";
  foreach(var d in rules.npcs)foreach(var e in d.schedule){var o=Find(e.objectId);if(o!=null&&o.GetComponent<WorldActivitySlot>()!=null)e.position=o.GetComponent<WorldActivitySlot>().Point-rules.Zone(e.zone).origin;}
  string officeAfter=FacilitySignature("workplace"),homeAfter=FacilitySignature("home");if(officeBefore!=officeAfter||homeBefore!=homeAfter)throw new Exception("Protected company or starter home changed");File.WriteAllText("Docs/FacilityStandardization/PROTECTED_LAYOUT.txt","Workspace "+officeBefore+" = "+officeAfter+"\nStarterHome "+homeBefore+" = "+homeAfter+"\n");
  Directory.CreateDirectory("Assets/_Game/Prefabs/Facilities");var template=UnityEngine.Object.Instantiate(Find("school-seat-2").gameObject);template.name="FacilityActivitySeat";template.transform.position=Vector3.zero;template.GetComponent<WorldInteractable>().id="";template.GetComponent<WorldInteractable>().zone="";template.GetComponent<WorldActivitySlot>().staffId="";PrefabUtility.SaveAsPrefabAsset(template,"Assets/_Game/Prefabs/Facilities/FacilityActivitySeat.prefab");UnityEngine.Object.DestroyImmediate(template);EditorUtility.SetDirty(rules);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();
 }
